// <auto-generated/>
using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using Fanex.Age.UI.Components.WinlossReportFilter;
using Sunplus.Agent.Model.Entities.Permission;
using Sunplus.Agent.Model.BL.Definitions;

namespace Fanex.Age.UI.Components
{
    public class Filter_Control : TplCore.Element.IComponent
    {
        #region Member Variables

        public const string SHOWALL = "all";
        public const string SHOWSB = "showsb";
        public const string SHOWCASINO = "showcasino";
        public const string SHOWRB = "showrb";
        public const string SHOW_NUMBER_GAME = "showng";
        public const string SHOW_IBC_BINGO = "showbi";
        public const string SHOW_P2P = "showp2p";
        public const string SHOW_LIVECASINO = "showlivecasino";
        public const string SHOW_VIRTUALSPORTS = "showvs";
        public const string SHOW_PROGRESSIVE_BONUS = "showprogressivebonus";
        public const string SHOW_KENO = "showkeno";
        public const string SHOW_LUCKY3 = "showlk3";
        public const string SHOW_HAPPY5 = "showhappy5";

        private bool _isShowed = true;
        private DateTime _dateFrom;
        private Dictionary<string, FilterElement> _filterCollections = null;
        private WinlossReportFilter_Template _template = null;
        private HttpRequest _request = null;

        #endregion



        #region Properties

        public bool IsShowed
        {
            get { return _isShowed; }
            set { _isShowed = value; }
        }

        #endregion



        #region Constructors

        public Filter_Control(IDictionary<string, FilterElement> filterCollections, HttpRequest request, DateTime dateFrom)
        {
            _filterCollections = filterCollections as Dictionary<string, FilterElement>;
            if (_filterCollections == null)
            {
                _filterCollections = new Dictionary<string, FilterElement>();
            }
            _dateFrom = dateFrom;
            _request = request;

            // Check permission,
            // Set show, hide
            // check, uncheck
            // Check no button was checked
            CheckPermission();

            _template = new WinlossReportFilter_Template();
        }

        #endregion



        #region Process

        public ICollection<KeyValuePair<string, bool>> AsCollection()
        {
            List<KeyValuePair<string, bool>> list = new List<KeyValuePair<string, bool>>();
            foreach (string elementName in _filterCollections.Keys)
            {
                if (string.Compare(elementName, SHOWALL) != 0)
                {
                    if (_filterCollections[elementName].Visible)
                    {
                        list.Add(new KeyValuePair<string, bool>(elementName, _filterCollections[elementName].Checked));
                    }
                }
            }

            return list;
        }

        #endregion


        #region Helpers

        private void Render()
        {
            _template.Filter.Clear();

            if (_isShowed)
            {
                FilterElement element = null;
                foreach (string key in _filterCollections.Keys)
                {
                    element = _filterCollections[key];
                    element.Render();
                    _template.Filter.Append(element.Content);
                }
            }
        }

        /// <summary>
        /// Check user permission on all items
        /// </summary>
        private void CheckPermission()
        {
            foreach (string elementName in _filterCollections.Keys)
            {
                if (string.Compare(elementName, SHOWSB) == 0)
                {
                    CheckPermission(true, SHOWSB);
                }
                else if (string.Compare(elementName, SHOWCASINO) == 0)
                {
                    CheckPermission(UserPermission.IsShowCasino, SHOWCASINO);
                }
                else if (string.Compare(elementName, SHOWRB) == 0)
                {
                    CheckPermission(UserPermission.IsShowRacing, SHOWRB);
                }
                else if (string.Compare(elementName, SHOW_IBC_BINGO) == 0)
                {
                    CheckPermission(UserPermission.IsShowBingoReport, SHOW_IBC_BINGO);
                }
                else if (string.Compare(elementName, SHOW_NUMBER_GAME) == 0)
                {
                    CheckPermission(UserPermission.IsShowNumberGame, SHOW_NUMBER_GAME);
                }
                else if (string.Compare(elementName, SHOW_P2P) == 0)
                {
                    CheckPermission(AppSettings.IsEnableP2P, SHOW_P2P);
                }
                else if (string.Compare(elementName, SHOW_LIVECASINO) == 0)
                {
                    CheckPermission(UserPermission.IsShowLiveCasino, SHOW_LIVECASINO);
                }
                else if (string.Compare(elementName, SHOW_VIRTUALSPORTS) == 0)
                {
                    CheckPermission(UserPermission.IsShowVirtualSports, SHOW_VIRTUALSPORTS);
                }
                else if (string.Compare(elementName, SHOW_PROGRESSIVE_BONUS) == 0)
                {
                    CheckPermission(UserPermission.IsShowCasino, SHOW_PROGRESSIVE_BONUS);
                }
                else if (string.Compare(elementName, SHOW_KENO) == 0)
                {
                    CheckPermission(UserPermission.EnableKeno, SHOW_KENO);
                }
                else if (string.Compare(elementName, SHOW_LUCKY3) == 0)
                {
                    CheckPermission(UserPermission.IsShowLucky3, SHOW_LUCKY3);
                }
            }

            UpdateSportBookItem();

            //Check cross date
            CheckCrossDateConstraint();

            UpdateItemAll();
        }

        /// <summary>
        /// Set nocheck status if user does not have permission 
        /// </summary>
        /// <param name="isAllowedPermission"></param>
        /// <param name="index"></param>
        /// <param name="paramName"></param>
        private void CheckPermission(bool isAllowedPermission, string paramName)
        {
            this._filterCollections[paramName].Visible = isAllowedPermission;
            this._filterCollections[paramName].Checked = GetCheckedParams(paramName);
        }

        /// <summary>
        /// Return true if the param is "on"
        /// </summary>
        /// <param name="paramName"></param>
        /// <returns></returns>
        private bool GetCheckedParams(string paramName)
        {
            string paramValue = _request[FilterElement.PREFIX_ELEMENT + paramName];

            if ((!string.IsNullOrEmpty(paramValue)) && (string.Compare(paramValue.ToLower(), "on") == 0))
            {
                return true;
            }
            else if ((!string.IsNullOrEmpty(paramValue)) && (string.Compare(paramValue.ToLower(), "off") == 0))
            {
                return false;
            }
            return string.IsNullOrEmpty(_request["FilterPostback"]);
        }

        /// <summary>
        /// Check cross date contrain
        /// </summary>
        private void CheckCrossDateConstraint()
        {
            DateTime boundDate = Sunplus.Agent.Model.BL.Definitions.AppSettings.SB_HR_FI_Date;

            //Set constraint of SB, HR, FI if FromDate is before the boundDate
            if (_dateFrom < boundDate)
            {
                foreach (string elementName in _filterCollections.Keys)
                {
                    if ((elementName == SHOWSB) || (elementName == SHOWRB))
                    {
                        if (_filterCollections[elementName].Checked)
                        {
                            _filterCollections[SHOWSB].Checked = true;
                            _filterCollections[SHOWRB].Checked = true;

                            break;
                        }
                    }
                }
            }
        }

        /// <summary>
        /// Update sport book item value
        /// </summary>
        private void UpdateSportBookItem()
        {
            if (!_filterCollections.ContainsKey(SHOWSB))
            {
                return;
            }

            bool isNoPermission = true;

            // Check if user have permission on any item
            foreach (string elementName in _filterCollections.Keys)
            {
                if (_filterCollections[elementName].Visible)
                {
                    isNoPermission = false;
                    break;
                }
            }

            // If user have permission, set sportbook item as request param
            if (isNoPermission)
            {
                _filterCollections[SHOWSB].Visible = false;
                _filterCollections[SHOWSB].Checked = true;
            }
            else
            {
                _filterCollections[SHOWSB].Visible = true;
                _filterCollections[SHOWSB].Checked = GetCheckedParams(SHOWSB);
            }
        }

        /// <summary>
        /// Update item all
        /// Item all will be showed when one of others was showed
        /// but it will not be showed when only one was showed.
        /// </summary>
        private void UpdateItemAll()
        {
            bool isNoPermission = true, isAll = true;

            // Check if user have permission on any item
            // Check if all item is check
            foreach (string elementName in _filterCollections.Keys)
            {
                if (_filterCollections[elementName].Visible)
                {
                    isNoPermission = false;
                    if (_filterCollections[elementName].Checked == false)
                    {
                        isAll = false;
                    }
                }
            }

            // If user have permission on any item
            if (isNoPermission)
            {
                _filterCollections[SHOWALL].Visible = false;
            }
            else
            {
                _filterCollections[SHOWALL].Visible = true;
                _filterCollections[SHOWALL].Checked = isAll;
            }
        }

        #endregion



        #region IComponent Members

        public void HideLinkedResources()
        {
            throw new NotImplementedException();
        }

        #endregion



        #region Overrides

        public override string ToString()
        {
            Render();
            return _template.ToString();
        }

        #endregion
    }
}
